mapper.select:
select t.ma_name,t.ma_name maName,t.remark,t.status_cd,t.status_cd statusCd,t.ma_id,t.ma_id
maId,t.community_id,t.community_id communityId,t.create_time createTime
from monitor_area t
where 1 =1

    and t.ma_name like concat('%', #{maName}, '%')


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.ma_id= #{maId}


    and t.community_id= #{communityId}

order by t.create_time desc

    limit #{page}, #{row}

